def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    from itertools import islice

    def chunks(it, size):
        it = iter(it)
        return iter(lambda: tuple(islice(it, size)), ())

    results = []
    processes = []

    for chunk in chunks(varargs, _max_length // len(cmd) - 1):
        full_cmd = cmd + chunk
        if color and os.name == 'posix':
            process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1, universal_newlines=False, preexec_fn=os.setsid, **kwargs)
        else:
            process = subprocess.Popen(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1, universal_newlines=False, **kwargs)
        processes.append(process)

        while len(processes) >= target_concurrency:
            for i, proc in enumerate(processes):
                if proc.poll() is not None:
                    stdout, stderr = proc.communicate()
                    results.append((proc.returncode, stdout))
                    del processes[i]
                    break

    for proc in processes:
        stdout, stderr = proc.communicate()
        results.append((proc.returncode, stdout))

    return results[0] if results else (0, b'')

