def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from functools import lru_cache, wraps
    from time import monotonic as _time_monotonic

    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)
        cache_times = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = args if typed else args + tuple(kwargs.items())
            now = timer()

            if key in cache_times and cache_times[key] + ttl < now:
                cache_times.pop(key)
                cache.cache_clear(key)

            if key not in cache_times:
                result = func(*args, **kwargs)
                cache_times[key] = now
                cache.cache_set(key, result)
            else:
                result = cache.cache_get(key)

            return result

        return wrapper

    return decorator

