def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    output = f"{indent_str}{self.__class__.__name__}("
    if debug:
        output += f"id={getattr(self, 'id', None)}, "
    output += ")\n"
    for attr, value in self.__dict__.items():
        if attr.startswith('_') or attr in ['doc', 'parent']:
            continue
        if hasattr(value, 'pretty'):
            output += f"{indent_str}  {attr}=\n{value.pretty(indent + 2, debug)}"
        else:
            output += f"{indent_str}  {attr}={value}\n"
    return output

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        indent_str = '  ' * indent
        pretty_repr = f"{indent_str}{self.__class__.__name__}("
        if debug:
            pretty_repr += f"id={self.id}, "
        pretty_repr += ")\n"
        for attr, value in vars(self).items():
            if attr.startswith('_'):
                continue
            if isinstance(value, list):
                pretty_repr += f"{indent_str}  {attr}=[\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        pretty_repr += item.pretty(indent + 2, debug)
                    else:
                        pretty_repr += f"{'  ' * (indent + 2)}{item},\n"
                pretty_repr += f"{indent_str}  ],\n"
            else:
                pretty_repr += f"{indent_str}  {attr}={value},\n"
        pretty_repr += f"{indent_str})"
        return pretty_repr

