                        new_args.append(left)
                    elif right[2] == left:
                        new_args.append(left)
                    elif right[1] == ('~', left):
                        new_args.append(('&', left, right[2]))
                    elif right[2] == ('~', left):
                        new_args.append(('&', left, right[1]))
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            elif op == '|':
                if isinstance(right, tuple) and right[0] == '&':
                    if right[1] == left:
                        new_args.append(left)
                    elif right[2] == left:
                        new_args.append(left)
                    elif right[1] == ('~', left):
                        new_args.append(('|', left, right[2]))
                    elif right[2] == ('~', left):
                        new_args.append(('|', left, right[1]))
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        else:
            new_args.append(expr)
    return new_args

