def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized = relativedelta()
    for attr in self._fields:
        value = getattr(self, attr)
        if value is not None:
            if attr in ['years', 'months']:
                normalized_value = int(value)
            elif attr in ['days', 'hours', 'minutes', 'seconds']:
                normalized_value = int(value)
                remainder = value - normalized_value
                if attr == 'days':
                    normalized.seconds += int(remainder * 24 * 3600)
                elif attr == 'hours':
                    normalized.seconds += int(remainder * 3600)
                elif attr == 'minutes':
                    normalized.seconds += int(remainder * 60)
            setattr(normalized, attr, normalized_value)
    # Normalize days to months and years
    while normalized.days >= 30:
        normalized.days -= 30
        normalized.months += 1
    while normalized.months >= 12:
        normalized.months -= 12
        normalized.years += 1
    return normalized

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] == 2:
        return tuple(s.encode('utf-8') for s in namefunc())
    else:
        return namefunc()

