            if not hide_stderr:
                print("Command failed with error:\n", e.stderr)
            raise e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")

    final_command = []
    for cmd in commands:
        if isinstance(cmd, str):
            cmd = cmd.split()
        final_command.extend(cmd)

    if isinstance(args, str):
        args = shlex.split(args)

    final_command.extend(args)

    if verbose:
        print("Running command: %s" % ' '.join(final_command))

    try:
        with subprocess.Popen(final_command, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT, cwd=cwd, env=env) as proc:
            stdout, stderr = proc.communicate()
            if proc.returncode != 0:
                raise subprocess.CalledProcessError(proc.returncode, final_command, output=stdout, stderr=stderr)
            if verbose:
                print(stdout.decode())
    except Exception as e:
        if verbose:
            print("An error occurred: %s" % e)
        raise

    return stdout.decode()

