                for sub_key, sub_value in value.value:
                    merged_mapping[sub_key.value] = sub_value
                merged_nodes[key_value][1].value = list(merged_mapping.items())
            else:
                merged_nodes[key_value] = (key, value)
        else:
            merged_nodes[key_value] = (key, value)

    return list(merged_nodes.values())

def deep_merge_nodes(nodes):
    from collections import defaultdict
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_nodes = defaultdict(list)

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, MappingNode):
            if key not in merged_nodes:
                merged_nodes[key] = [(key_node, value_node)]
            else:
                existing_key_node, existing_value_node = merged_nodes[key][0]
                existing_value_dict = dict(existing_value_node.value)
                new_value_dict = dict(value_node.value)
                existing_value_dict.update(new_value_dict)
                existing_value_node.value = list(existing_value_dict.items())
        else:
            merged_nodes[key] = [(key_node, value_node)]

    return [item for sublist in merged_nodes.values() for item in sublist]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import defaultdict

    def merge_value(existing, new):
        if isinstance(existing, ruamel.yaml.nodes.MappingNode) and isinstance(new, ruamel.yaml.nodes.MappingNode):
            existing_dict = {k.value: v for k, v in existing.value}
            new_dict = {k.value: v for k, v in new.value}
            merged_dict = defaultdict(list)
            for k, v in existing_dict.items():
                merged_dict[k].append(v)
            for k, v in new_dict.items():
                merged_dict[k].append(v)
            merged_value = []
            for k, v in merged_dict.items():
                if len(v) > 1:
                    merged_value.append((ruamel.yaml.nodes.ScalarNode(tag=ruamel.yaml.scalarstring.PlainScalarString.tag, value=k), merge_value(v[0], v[1])))
                else:
                    merged_value.append((ruamel.yaml.nodes.ScalarNode(tag=ruamel.yaml.scalarstring.PlainScalarString.tag, value=k), v[0]))
            return ruamel.yaml.nodes.MappingNode(tag=ruamel.yaml.map.Map.tag, value=merged_value)
        else:
            return new

    merged_nodes = defaultdict(list)
    for key_node, value_node in nodes:
        key = key_node.value
        merged_nodes[key].append(value_node)

    result = []
    for key, values in merged_nodes.items():
        merged_value = values[0]
        for value in values[1:]:
            merged_value = merge_value(merged_value, value)
        result.append((ruamel.yaml.nodes.ScalarNode(tag=ruamel.yaml.scalarstring.PlainScalarString.tag, value=key), merged_value))

    return result

