def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    from borgmatic.commands.arguments import global_arguments, parse_subparser_arguments

    def generate_argument_completions(parser):
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for _, subparser in action.choices.items():
                    yield from generate_argument_completions(subparser)
            elif action.option_strings:
                yield ' '.join(action.option_strings)

    global_parser = argparse.ArgumentParser(add_help=False)
    global_arguments(global_parser)
    subparsers, _ = parse_subparser_arguments(global_parser)

    completions = []
    for subcommand, subparser in subparsers.choices.items():
        completions.extend(['borgmatic', subcommand])
        completions.extend(generate_argument_completions(subparser))

    return '\n'.join(f'complete -W "{comp}" borgmatic' for comp in set(' '.join(completions).split()))

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    suffix = size[-1]
    if suffix.isdigit():
        return int(size)
    try:
        size_value = int(size[:-1])
    except ValueError:
        raise ValueError(f"Invalid size format: {size}")

    suffixes = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
    if suffix.upper() in suffixes:
        return size_value * suffixes[suffix.upper()]
    else:
        raise ValueError(f"Invalid size suffix: {suffix}")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

