def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import os
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:
        # POSIX
        pattern = r"(?:(?P<quote>[\"'])(?P<value>.*?)(?P=quote)|(?P<word>[^\s]+))"
    elif platform == 0:
        # Windows/CMD
        pattern = r"\"([^\"]*)\"|'([^']*)'|([\^]*[^ \^]+)"
    else:
        raise ValueError("Unsupported platform")

    matches = re.finditer(pattern, s)
    result = []

    for match in matches:
        if match.group('quote'):
            result.append(match.group('value'))
        elif match.group('word'):
            result.append(match.group('word'))
        else:
            result.append(match.group(0).replace('^', ''))

    return result

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        import os
        platform = 1 if os.name != 'nt' else 0

    if platform == 1:  # POSIX
        # Simple regex for POSIX command-line splitting
        return re.findall(r'(?:[^\s\'"]|\'[^\']*\'|"[^"]*")+', s)
    elif platform == 0:  # Windows/CMD
        # Simple regex for Windows/CMD command-line splitting
        return re.findall(r'(?:[^"^\s]+|"[^"]*")+', s)
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1 (POSIX), or 0 (Windows/CMD).")

