def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename) as config_file:
                config.read_file(config_file)
                if overrides:
                    for section, options in overrides.items():
                        if not config.has_section(section):
                            config.add_section(section)
                        for key, value in options.items():
                            config.set(section, key, value)

                if resolve_env:
                    config.read_env_vars()

                config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}

        except (configparser.Error, IOError) as e:
            log_record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
            log_records.append(log_record)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
