    import logging
    import json
    import os

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}
                if overrides:
                    config.update(overrides)
                config_dict[filename] = config
        except Exception as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=True)
