def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    try:
        # Try parsing as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD (XML)
        root = ET.fromstring(document)
        xrd = {}

        # Extract relevant information from the XRD XML
        for child in root:
            if child.tag.endswith('}subject'):
                xrd['subject'] = child.text
            elif child.tag.endswith('}alias'):
                xrd.setdefault('aliases', []).append(child.text)
            elif child.tag.endswith('}link'):
                link = {}
                for attr, value in child.attrib.items():
                    link[attr] = value
                xrd.setdefault('links', []).append(link)

        return xrd

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        import xml.etree.ElementTree as ET
    except ImportError as e:
        raise RuntimeError("Required module not found: {}".format(e))

    try:
        # Try to parse as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ET.fromstring(document)
            xrd_namespace = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            subject = root.find('xrd:Subject', xrd_namespace).text
            aliases = [alias.text for alias in root.findall('xrd:Alias', xrd_namespace)]
            links = []
            for link in root.findall('xrd:Link', xrd_namespace):
                link_dict = {'href': link.get('href')}
                for attr in ['rel', 'type', 'template']:
                    if link.get(attr):
                        link_dict[attr] = link.get(attr)
                links.append(link_dict)
            return {'subject': subject, 'aliases': aliases, 'links': links}
        except (ET.ParseError, AttributeError):
            raise ValueError("The provided document is neither valid JSON nor XRD")

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    current = dic
    for k in keys[:-1]:
        if k not in current:
            current[k] = {}
        current = current[k]
    if keys:
        current[keys[-1]] = val
    else:
        current[key] = val

